miss = dict(NEW)
for f in glob.glob(os.path.join(ROOT, 'src', '**', '*.js'), recursive=True):
    s = open(f).read(); o = s
    for old, new in NEW.items():
        q = "'" + old + "'"
        if q in s:
            s = s.replace(q, "'" + new + "'"); miss.pop(old, None)
    if s != o: open(f, 'w').write(s); print('updated', os.path.relpath(f, ROOT))
print('missing', list(miss))
